import type {
	AppBuildContext,
	AppBuildResult,
	AppDeployContext,
	Application,
	ApplicationInstance,
} from "@teambit/application";
import { AppContext } from "@teambit/application";
import { ComponentID } from "@teambit/component-id";
import findRoot from "find-root";
import { Port } from "@teambit/toolbox.network.get-port";
import { build as esbuildBundle } from "esbuild";
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "fs";
import { dirname, join } from "path";
import type { Compiler } from "@teambit/compiler";
import type { Workspace } from "@teambit/workspace";
import { WorkspaceAspect } from "@teambit/workspace";
import { ScopeAspect, ScopeMain } from "@teambit/scope";
import { BuilderAspect, BuilderMain } from "@teambit/builder";
import type { Artifact, ArtifactList, ArtifactVinyl } from "@teambit/builder";
import type { Component, ComponentMain } from "@teambit/component";
import { ComponentAspect } from "@teambit/component";
import { fileURLToPath, pathToFileURL } from "node:url";
import { findCapsuleAppBundle, copyDirRecursive } from "./bundle-utils.js";
import {
	PlatformBuildFn,
	PlatformDeployFn,
	PlatformOptions,
} from "./platform-options.js";
import { GatewayContext } from "./gateway-context.js";
import { PlatformService, PlatformServiceModule } from "./platform-service.js";
import { PlatformLayer } from "./platform-layer.js";
import { PlatformBuildContext } from "./platform-build-context.js";
import {
	backendOrchestratorSource,
	PlatformBundleManifest,
} from "./backend-orchestrator-source.js";

export class Platform implements Application {
	constructor(
		/**
		 * name of the platform
		 */
		readonly name: string,

		/**
		 * backends of the platform.
		 */
		readonly backends: PlatformLayer,

		/**
		 * frontends of the platform
		 */
		readonly frontends: PlatformLayer,

		/**
		 * custom build function.
		 */
		readonly userBuild?: PlatformBuildFn,

		/**
		 * custom deploy function.
		 */
		readonly userDeploy?: PlatformDeployFn,
	) {}

  readonly platform = true;

	async run(context: AppContext): Promise<ApplicationInstance> {
		const backend = await this.runPlatformLayer(
			"backend",
			context,
			this.backends,
		);
		const frontends = this.frontends.mainPortRange
			? this.frontends
			: { ...this.frontends, mainPortRange: [3000, 3100] as [number, number] };

		const frontend = await this.runPlatformLayer("frontend", context, frontends, backend);

		// prefer the frontend URL for the user-facing port; fall back to backend
		// when the platform has no frontend layer.
		const primary = frontend?.port ? frontend : backend;
		const port = typeof primary === "number" ? primary : primary.port;

		return {
			appName: this.name,
			port,
		};
	}

	private listPlatformModules(
		platformLayer: PlatformLayer,
		context: AppContext,
		mainPort?: number,
	): Promise<PlatformServiceModule[]> {
		const [from, to] = platformLayer.portRange || [5000, 5100];
		const usedPorts = mainPort ? [mainPort] : undefined;

		return Promise.all(
			platformLayer.services?.map(async (service) => {
				const targetPort = usedPorts
					? await Port.getPort(from, to, usedPorts)
					: undefined;
				const platformServiceModule = await this.loadPlatformService(
					service,
					targetPort,
					context,
				);
				// eslint-disable-next-line @typescript-eslint/no-unused-expressions
				usedPorts && usedPorts.push(targetPort);
				return platformServiceModule;
			}) || [],
		);
	}

	getCloudWorkspaceUrl(port: number) {
		const workspacePath = process.env.VSCODE_PROXY_URI;
		if (!workspacePath) return undefined;
		if (!port) return undefined;
		const updatedPath = workspacePath.endsWith('/')
			? workspacePath.substring(0, workspacePath.length - 1)
			: workspacePath;
			
		return updatedPath.replace('{{port}}', port.toString());
	}

	async runPlatformLayer(
		name: string,
		context: AppContext,
		platformLayer: PlatformLayer,
		apiGateway?: ApplicationInstance,
	): Promise<ApplicationInstance> {
		if (!platformLayer) return {};
		const [from, to] = platformLayer.portRange || [5000, 5100];
		const [gatewayFrom, gatewayTo] = platformLayer.mainPortRange || [from, to];
		const gatewayPort = await Port.getPort(gatewayFrom, gatewayTo);
		const platformServiceModules =
			(await this.listPlatformModules(platformLayer, context, gatewayPort)) ||
			[];
		const serviceEnvVars = this.computeEnvVars(
			platformServiceModules.map((serviceModule) => {
				return {
					appName: serviceModule?.module?.name || serviceModule.componentId.name,
					port: serviceModule.context.port,
				};
			}),
		);

		const instances: ApplicationInstance[] = await Promise.all(
			platformServiceModules.map(async (platformService) => {
				if (platformService.url) {
					return {
						appName: platformService.module.name,
						url: platformService.url,
					};
				}

				const platformContext = AppContext.compose(platformService.context, {
					envVariables: serviceEnvVars,
				});
				const appInstance = await platformService.module.run(platformContext);
				const isNumber = typeof appInstance === "number";
				const appName = platformService.module.name;
				const port = isNumber ? appInstance : appInstance.port;

				if (port) {
					let retries = 0;
					while (retries < 10) {
						try {
							await fetch(`http://localhost:${port}`);
							break;
						} catch (e) {
							retries++;
							await new Promise((resolve) => setTimeout(resolve, 1000));
						}
					}
					if (retries === 10) {
						throw new Error(
							`service ${appName} did not start after 10 retries.`,
						);
					}
				}

				console.log(
					`[${platformService.module.name}]: running on port ${port}`,
				);

				return {
					appName,
					port,
				};
			}) || [],
		);

		const mainService = await this.loadPlatformService(
			platformLayer.main,
			gatewayPort,
			context,
		);
		const envVars = this.computeEnvVars(
			apiGateway ? instances.concat([apiGateway]) : instances,
			apiGateway,
		);

		const gatewayContext = new GatewayContext(
			mainService.context,
			instances,
			gatewayPort,
			envVars,
		);

		const gatewayInstance = await mainService.module.run(gatewayContext);
		console.log(`${name} server running on ${gatewayContext.port}`);
		return this.getAppInstance(gatewayInstance, mainService);
	}

	private computeEnvVars(
		instances: ApplicationInstance[],
		apiGateway?: ApplicationInstance,
	): Record<string, string> {
		return instances.reduce<Record<string, string>>((acc, instance) => {
			const workspaceUrl = this.getCloudWorkspaceUrl(instance.port);
			if (apiGateway && !acc?.BACKEND_URL) {
				acc.BACKEND_URL = instance.url || workspaceUrl || `http://localhost:${instance.port}`;
			}

			if (!instance?.appName) {
				console.warn(
					`warning: there is a server listening to port ${instance.port} but without an app name specified. an env variable would not be set.`,
				);
				return acc;
			}
			// @ts-ignore-next-line
			const varName = `${instance.appName.toUpperCase()}_URL`.replaceAll(
				"-",
				"_",
			);
			acc[varName] = instance.url || workspaceUrl || `http://localhost:${instance.port}`;
			return acc;
		}, {});
	}

	getAppInstance(
		res: number | ApplicationInstance,
		service?: PlatformServiceModule,
	) {
		if (typeof res !== "number") {
			const appName = res.appName || service.name;

			return {
				appName,
				...res,
			};
		}

		return {
			appName: service.name,
			port: res,
		};
	}

	private getWorkspace(context: AppContext): Workspace | undefined {
		try {
			const workspace = context.getAspect<Workspace>(WorkspaceAspect.id);
			return workspace;
		} catch {
			return undefined;
		}
	}

	async getComponent(context: AppContext, id: ComponentID): Promise<Component> {
		const scope = context.getAspect<ScopeMain>(ScopeAspect.id);
		const componentAspect = context.getAspect<ComponentMain>(
			ComponentAspect.id,
		);
		const host = componentAspect.getHost();
		const hasId = await host.hasIdNested(id);

		if (hasId) {
			return host.get(id);
		}

		await scope.import([id]);
		return host.get(id);
	}

	async loadPlatformService(
		serviceOpts: PlatformService,
		targetPort: number,
		context: AppContext,
	): Promise<PlatformServiceModule> {
		const workspace = this.getWorkspace(context);
		// const componentAspect = context.getAspect<ComponentMain>(ComponentAspect.id);
		// const host = componentAspect.getHost();
		const hasOpts = Array.isArray(serviceOpts);
		const servicePath = hasOpts ? await serviceOpts[0] : await serviceOpts;

		const options = hasOpts ? serviceOpts[1] : {};

		const urlPath = fileURLToPath(servicePath);
		const root = await findRoot(urlPath);
		const packageJsonString = readFileSync(join(root, "package.json")).toString(
			"utf-8",
		);
		const packageJson = JSON.parse(packageJsonString);
		const componentId = ComponentID.fromObject(packageJson.componentId);
		const isSelf =
			context.appComponent.id.toStringWithoutVersion() ===
			componentId.toStringWithoutVersion();
		const isInWorkspace = workspace
			? await workspace.hasId(componentId)
			: false;
		const shouldReturnRemote =
			(options.forceRemote && options.remoteUrl) ||
			(!isInWorkspace && Boolean(options.remoteUrl)) ||
			!workspace;

		const remoteUrl = shouldReturnRemote ? options.remoteUrl : undefined;

		const packageName = packageJson.name;
		const workspacePath = isInWorkspace
			? workspace.componentDir(componentId)
			: root;

		const appComponent = await this.getComponent(context, componentId);

		const serviceContext = AppContext.compose(context, {
			port: targetPort,
			workspaceComponentPath: workspacePath,
			hostRootDir: root,
			appComponent,
		});

		const path = isSelf
			? urlPath
			: this.findBitApp(context, componentId, root, packageJson.main);

		const serviceModule = await import(pathToFileURL(path).href);
		let service = serviceModule.default;
		// check for commonjs module, as it exports the default to module.default.default
		if (service.default) {
			service = service.default;
		}

		if (!serviceModule.default)
			throw new Error(`service in path ${path} has no "export default".`);
		const serviceName = service.name;

		return {
			module: service,
			context: serviceContext,
			url: remoteUrl,
			name: serviceName,
			componentId,
			packageName,
		};
	}

	private findBitApp(
		context: AppContext | undefined,
		id: ComponentID,
		root: string,
		main: string,
	) {
		let distDir = "dist";
		if (context) {
			try {
				const compiler: Compiler = context.env.getCompiler();
				distDir = compiler.getDistDir?.() || "dist";
			} catch {
				// compiler unavailable — use default dist dir
			}
		}
		const possibleLocations = [
			join(root, distDir, `${id.name}.bit-app.js`),
			join(root, distDir, `${id.name}.bit-app.mjs`),
			join(root, main),
		];

		return possibleLocations.find((possiblePath) => {
			return existsSync(possiblePath);
		});
	}

	private async createPlatformContext(
		context: AppBuildContext,
	): Promise<PlatformBuildContext> {
		const scope = context.getAspect<ScopeMain>(ScopeAspect.id);
		const builder = context.getAspect<BuilderMain>(BuilderAspect.id);
		const backendPlatformModules = await this.listPlatformModules(
			this.backends,
			context,
		);
		const frontendPlatformModules = await this.listPlatformModules(
			this.frontends,
			context,
		);
		const platformServicesModules = [
			...backendPlatformModules,
			...frontendPlatformModules,
		];

		const componentIds = platformServicesModules.map((platformModule) => {
			return platformModule.componentId;
		});

		const components = await scope.getMany(componentIds);
		const platformServices = platformServicesModules.map((platformService) => {
			const platformComponent = components.find((component) => {
				return (
					component.id.toStringWithoutVersion() ===
					platformService.componentId.toStringWithoutVersion()
				);
			});
			const artifacts = builder.getArtifacts(platformComponent);
			const isBackend = backendPlatformModules.find((backend) => {
				return (
					backend.componentId.toStringWithoutVersion() ===
					platformService.componentId.toStringWithoutVersion()
				);
			});

			return {
				type: isBackend ? "backend" : "frontend",
				componentId: platformService.componentId,
				artifacts,
				name: platformService.name,
				url: platformService.url,
				component: platformComponent,
			};
		});

		const mainBackend = await this.loadPlatformService(
			this.backends.main,
			context.port,
			context,
		).then(async (backend) => {
			const component = await scope.get(backend.componentId);
			return {
				type: "backend",
				componentId: backend.componentId,
				name: backend.name,
				url: backend.url,
				component: component,
				artifacts: builder.getArtifacts(component),
			};
		});

		const mainFrontend = await this.loadPlatformService(
			this.frontends.main,
			context.port,
			context,
		).then(async (frontend) => {
			const component = await scope.get(frontend.componentId);
			return {
				type: "frontend",
				componentId: frontend.componentId,
				name: frontend.name,
				url: frontend.url,
				component: component,
				artifacts: builder.getArtifacts(component),
			};
		});

		const platformContext = Object.assign(context, {
			platformServices,
			mainFrontend,
			mainBackend,
		});

		return platformContext;
	}

	async build(context: AppBuildContext): Promise<AppBuildResult> {
		const platformContext = await this.createPlatformContext(context);
		await this.assemblePlatformBundle(context, platformContext);
		platformContext.bundlePath = this.getBundleDir(context);

		const userResult = this.userBuild ? await this.userBuild(platformContext) : {};
		const userArtifacts = (userResult as AppBuildResult).artifacts || [];

		return {
			...userResult,
			artifacts: [
				{
					name: "platform-bundle",
					globPatterns: [`${context.artifactsDir}/platform-bundle/**`],
				},
				...userArtifacts,
			],
		};
	}

	async deploy(context: AppDeployContext) {
		if (!this.userDeploy) return {};
		const platformContext = await this.createPlatformContext(context);
		platformContext.bundlePath = this.getBundleDir(context);

		return this.userDeploy(platformContext);
	}

	private getBundleDir(context: AppBuildContext | AppDeployContext): string {
		// AppBuildContext and AppDeployContext both expose `capsule` and
		// `artifactsDir` via the shared base; the bundle is staged at the same
		// path during build and read back during deploy.
		const ctx = context as AppBuildContext;
		return join(ctx.capsule.path, ctx.artifactsDir, "platform-bundle");
	}

	private async assemblePlatformBundle(
		context: AppBuildContext,
		platformContext: PlatformBuildContext,
	): Promise<string> {
		const bundleDir = this.getBundleDir(context);
		mkdirSync(bundleDir, { recursive: true });

		const scope = context.getAspect<ScopeMain>(ScopeAspect.id);
		const builder = context.getAspect<BuilderMain>(BuilderAspect.id);

		const manifest: PlatformBundleManifest = {
			name: this.name,
			gateway: { name: platformContext.mainBackend.name, entry: "" },
			frontend: { name: platformContext.mainFrontend.name, dir: "frontend" },
			services: {},
		};

		const capsuleNetwork = (context as any).capsuleNetwork;

		// gateway
		const gatewayDir = join(bundleDir, "gateway");
		mkdirSync(gatewayDir, { recursive: true });
		const gatewayMeta = await this.copyOrBundleService(
			builder, platformContext.mainBackend, scope, gatewayDir, capsuleNetwork, this.backends.main,
		);
		manifest.gateway.entry = gatewayMeta.entry
			? `gateway/${gatewayMeta.entry}`
			: "";

		// frontend
		const frontendDir = join(bundleDir, "frontend");
		mkdirSync(frontendDir, { recursive: true });
		const frontendMeta = await this.copyOrBundleService(
			builder, platformContext.mainFrontend, scope, frontendDir, capsuleNetwork, this.frontends.main,
		);
		if (frontendMeta.entry) {
			manifest.frontend.entry = `frontend/${frontendMeta.entry}`;
		}

		// backend services (exclude the mainBackend gateway itself)
		const mainBackendId = platformContext.mainBackend.componentId.toStringWithoutVersion();
		const backendServices = platformContext.platformServices.filter(
			(svc) =>
				svc.type === "backend" &&
				svc.componentId.toStringWithoutVersion() !== mainBackendId,
		);

		for (const svc of backendServices) {
			const svcDir = join(bundleDir, "services", svc.name);
			mkdirSync(svcDir, { recursive: true });
			const meta = await this.copyOrBundleService(
				builder, svc, scope, svcDir, capsuleNetwork,
			);
			if (meta.entry) {
				manifest.services[svc.name] = {
					entry: `services/${svc.name}/${meta.entry}`,
				};
			}
		}

		writeFileSync(
			join(bundleDir, "manifest.json"),
			`${JSON.stringify(manifest, null, 2)}\n`,
		);

		const orchestratorPath = join(bundleDir, "backend.cjs");
		writeFileSync(orchestratorPath, backendOrchestratorSource);
		chmodSync(orchestratorPath, 0o755);

		return bundleDir;
	}

	private async copyArtifactBytes(
		builder: BuilderMain,
		component: Component | undefined,
		componentId: ComponentID,
		scope: ScopeMain,
		destDir: string,
		capsuleNetwork?: any,
	): Promise<{ entry?: string }> {
		if (!component) return {};
		const idStr = componentId.toStringWithoutVersion();

		// prefer reading from the capsule filesystem (works when components
		// were built together in the same pipeline, before snap)
		if (capsuleNetwork) {
			const appBundleDir = findCapsuleAppBundle(capsuleNetwork, componentId);
			if (appBundleDir) {
				return copyDirRecursive(appBundleDir, destDir);
			}
		}

		// fallback: read from stored artifacts (pre-snapped components)
		const list: ArtifactList<Artifact> = builder.getArtifacts(component);
		const vinyls: ArtifactVinyl[] = [];
		if (list && list.length > 0) {
			for (const artifact of list) {
				if (artifact.name !== "app-bundle") continue;
				const fileVinyls = await artifact.files.getVinylsAndImportIfMissing(
					componentId,
					scope.legacyScope,
				);
				vinyls.push(...fileVinyls);
			}
		}

		if (vinyls.length === 0) {
			const hasCapsule = capsuleNetwork?.graphCapsules?.getCapsuleIgnoreVersion(componentId);
			const hint = hasCapsule
				? `The capsule exists but its "app-bundle" artifact directory was not found. ` +
				  `This usually means the component's build task has not run yet (cross-env build ordering issue).`
				: `The component was not found in the capsule network.`;
			throw new Error(
				`[platform] no "app-bundle" artifact found for "${idStr}". ${hint}`,
			);
		}

		let entry: string | undefined;
		const stripPrefix = "artifacts/app-bundle/";
		for (const v of vinyls) {
			let rel = v.relative || v.basename;
			if (!rel) continue;
			if (rel.startsWith(stripPrefix)) rel = rel.slice(stripPrefix.length);
			const target = join(destDir, rel);
			mkdirSync(dirname(target), { recursive: true });
			writeFileSync(target, v.contents as Buffer);
			if (
				!entry &&
				rel.endsWith(".cjs") &&
				!rel.endsWith(".cjs.map") &&
				!rel.endsWith(".map.cjs")
			) {
				entry = rel.split("/").pop();
			}
		}
		return { entry };
	}

	private async copyOrBundleService(
		builder: BuilderMain,
		svc: { component?: Component; componentId?: ComponentID; name: string },
		scope: ScopeMain,
		destDir: string,
		capsuleNetwork?: any,
		serviceOpts?: PlatformService,
	): Promise<{ entry?: string }> {
		const idStr = svc.componentId?.toStringWithoutVersion() || svc.name;
		try {
			return await this.copyArtifactBytes(
				builder, svc.component, svc.componentId, scope, destDir, capsuleNetwork,
			);
		} catch (err) {
			const msg = String(err);
			if (!msg.includes("app-bundle")) throw err;
			console.log(`[platform] no app-bundle artifact for "${idStr}", falling back to esbuild bundling`);
		}

		const entryPath = await this.resolveServiceEntry(svc.componentId, serviceOpts);
		if (!entryPath) {
			console.warn(`[platform] could not resolve entry point for "${idStr}", skipping`);
			return {};
		}

		console.log(`[platform] bundling "${idStr}" from ${entryPath}`);
		const moduleName = `${svc.name}.module.cjs`;
		const entryName = `${svc.name}.cjs`;
		await esbuildBundle({
			entryPoints: [entryPath],
			bundle: true,
			platform: "node",
			outfile: join(destDir, moduleName),
		});

		const bootSource = [
			`const mod = require('./${moduleName}');`,
			`let app = mod.default || mod;`,
			`if (app && app.default) app = app.default;`,
			`const port = parseInt(process.env.PORT || '3000', 10);`,
			`const services = [];`,
			`const SUFFIX = '__PLATFORM_SERVICE_URL';`,
			`for (const [k, v] of Object.entries(process.env)) {`,
			`  if (!k.endsWith(SUFFIX) || k.length === SUFFIX.length) continue;`,
			`  if (typeof v !== 'string' || !/^https?:\\/\\//i.test(v)) continue;`,
			`  services.push({ appName: k.slice(0, -SUFFIX.length).toLowerCase().replace(/_/g, '-'), url: v });`,
			`}`,
			`if (typeof app.run === 'function') {`,
			`  app.run({ port, services }).catch(function (e) { console.error(e); process.exit(1); });`,
			`}`,
		].join("\n");
		writeFileSync(join(destDir, entryName), bootSource);

		console.log(`[platform] bundled "${idStr}" → ${entryName}`);
		return { entry: entryName };
	}

	private async resolveServiceEntry(
		componentId: ComponentID | undefined,
		serviceOpts?: PlatformService,
	): Promise<string | undefined> {
		if (serviceOpts) {
			const hasOpts = Array.isArray(serviceOpts);
			const servicePath = hasOpts ? await serviceOpts[0] : await serviceOpts;
			const urlPath = fileURLToPath(servicePath);
			const root = findRoot(urlPath);
			const packageJsonString = readFileSync(join(root, "package.json")).toString("utf-8");
			const packageJson = JSON.parse(packageJsonString);
			const id = componentId || ComponentID.fromObject(packageJson.componentId);
			return this.findBitApp(undefined, id, root, packageJson.main);
		}

		if (!componentId) return undefined;
		const packageName = componentId.toStringWithoutVersion().replace(/\//g, ".").replace(/\./g, "/");
		try {
			const resolved = fileURLToPath(import.meta.resolve(`@${packageName}`));
			const root = findRoot(resolved);
			const packageJsonString = readFileSync(join(root, "package.json")).toString("utf-8");
			const packageJson = JSON.parse(packageJsonString);
			return this.findBitApp(undefined, componentId, root, packageJson.main);
		} catch {
			return undefined;
		}
	}

	static from(options: PlatformOptions) {
		return new Platform(
			options.name,
			options.backends,
			options.frontends,
			options.build,
			options.deploy,
		);
	}
}
